#include <stdio.h>
int sum_many(int a, int b, int c, int d, int e, int f) {
    return a + b + c + d + e + f;
}
void mutate(int *p, int val) {
    *p = val;
}
int main() {
    int s = sum_many(19, 20, 21, 22, 23, 24);
    printf("sum: %d\n", s);
    int x = 0;
    mutate(&x, 1900);
    printf("mutated: %d\n", x);
    return 0;
}
